      private void Anim_CircularStretchTwice(Sprite sprite)
      {
          if (sprite.data[2] == 0)
              HandleStartAffineAnim(sprite);

          if (sprite.data[2] > 40)
          {
              HandleSetAffineData(sprite, 256, 256, 0);
              ResetSpriteAfterAnim(sprite);
              sprite.callback = WaitAnimEnd;
          }
          else
          {
              short var_ = unchecked((short)((sprite.data[2] * 512 / 40) % 256));

              sprite.data[4] = Sin(var_, 32) + 256;
              sprite.data[5] = Cos(var_, 32) + 256;
              HandleSetAffineData(sprite, sprite.data[4], sprite.data[5], 0);
          }

          sprite.data[2]++;
      }


      private void Anim_HorizontalVibrate(Sprite sprite)
      {
          if (sprite.data[2] > 40)
          {
              sprite.callback = WaitAnimEnd;
              sprite.x2 = 0;
          }
          else
          {
              sbyte sign;
              if (((sprite.data[2] & 1) == 0))
                  sign = unchecked((sbyte)(1));
              else
                  sign = unchecked((sbyte)(-1));

              sprite.x2 = Sin((sprite.data[2] * 128 / 40) % 256, 6) * sign;
          }

          sprite.data[2]++;
      }


      private void HorizontalSlide(Sprite sprite)
      {
          TryFlipX(sprite);

          if (sprite.data[2] > sprite.data[0])
          {
              sprite.callback = WaitAnimEnd;
              sprite.x2 = 0;
          }
          else
