      private void BackAndLunge_2(Sprite sprite)
      {
          byte rotation;

          TryFlipX(sprite);
          sprite.x2 -= sprite.data[7];
          sprite.data[7]++;
          rotation = unchecked((byte)((sprite.data[5] * 6) / sprite.data[6]));

          if (++sprite.data[5] > sprite.data[6])
              sprite.data[5] = sprite.data[6];

          HandleSetAffineData(sprite, 256, 256, rotation * 256);

          if (sprite.x2 < -8)
          {
              sprite.x2 = -8;
              sprite.data[4] = 2;
              sprite.data[3] = 0;
              sprite.data[2] = rotation;
              sprite.callback = BackAndLunge_3;
          }

          TryFlipX(sprite);
      }


      private void BackAndLunge_3(Sprite sprite)
      {
          TryFlipX(sprite);

          if (sprite.data[3] > 11)
          {
              sprite.data[2] -= 2;
              if (sprite.data[2] < 0)
                  sprite.data[2] = 0;

              HandleSetAffineData(sprite, 256, 256, sprite.data[2] << 8);
              if (sprite.data[2] == 0)
                  sprite.callback = BackAndLunge_4;
          }
          else
          {
              sprite.x2 += sprite.data[4];
              sprite.data[4] *= -1;
              sprite.data[3]++;
          }

          TryFlipX(sprite);
      }


      private void BackAndLunge_4(Sprite sprite)
