      private void BackFlip_1(Sprite sprite)
      {
          TryFlipX(sprite);
          sprite.x2 = Cos(sprite.data[4], 16) - 8;
          sprite.y2 = Sin(sprite.data[4], 16) - 8;

          if (sprite.data[4] > 63)
          {
              sprite.data[2] = 160;
              sprite.data[3] = 10;
              sprite.callback = BackFlip_2;
          }
          sprite.data[4] += 8;
          if (sprite.data[4] > 64)
              sprite.data[4] = 64;

          TryFlipX(sprite);
