      private void BackFlip_2(Sprite sprite)
      {
          TryFlipX(sprite);

          if (sprite.data[3] > 0)
          {
              sprite.data[3]--;
          }
          else
          {
              int rotation;

              sprite.x2 = Cos(sprite.data[2], 5) - 4;
              sprite.y2 = -(Sin(sprite.data[2], 5)) + 4;
              sprite.data[2] -= 4;
              rotation = sprite.data[2] - 32;
              HandleSetAffineData(sprite, 256, 256, rotation * 512);

              if (sprite.data[2] <= 32)
