      private void Figure8(Sprite sprite)
      {
          TryFlipX(sprite);
          sprite.data[6] += 4;
          sprite.x2 = -(Sin(sprite.data[6], 16));
          sprite.y2 = -(Sin((sprite.data[6] * 2) & 0xFF, 8));
          if (sprite.data[6] > 192 && sprite.data[7] == 1)
          {
              HandleSetAffineData(sprite, 256, 256, 0);
              sprite.data[7]++;
          }
          else if (sprite.data[6] > 64 && sprite.data[7] == 0)
          {
              HandleSetAffineData(sprite, -256, 256, 0);
              sprite.data[7]++;
          }

          if (sprite.data[6] > 255)
          {
              sprite.x2 = 0;
              sprite.y2 = 0;
              HandleSetAffineData(sprite, 256, 256, 0);
              ResetSpriteAfterAnim(sprite);
              sprite.callback = WaitAnimEnd;
          }
          TryFlipX(sprite);
      }


      private void Anim_FlashYellow(Sprite sprite)
      {
          if (++sprite.data[2] == 1)
          {
              sprite.data[7] = OBJ_PLTT_ID(sprite.oam.paletteNum);
              sprite.data[6] = 0;
              sprite.data[5] = 0;
              sprite.data[4] = 0;
          }

          if (sYellowFlashData[sprite.data[6]][1] == 255)
          {
              sprite.callback = WaitAnimEnd;
          }
          else
          {
              if (sprite.data[4] == 1)
              {
                  if (sYellowFlashData[sprite.data[6]][0] != 0)
                      BlendPalette(sprite.data[7], 16, 16, RGB_YELLOW);
                  else
                      BlendPalette(sprite.data[7], 16, 0, RGB_YELLOW);

                  sprite.data[4] = 0;
              }

              if (sYellowFlashData[sprite.data[6]][1] == sprite.data[5])
              {
                  sprite.data[4] = 1;
                  sprite.data[5] = 0;
                  sprite.data[6]++;
              }
              else
              {
                  sprite.data[5]++;
              }
          }
      }


