          byte id = unchecked((byte)(sprite.data[0] = AddNewAnim()));
          sAnims[id].rotation = 4;
          DeepVerticalSquishBounce(sprite);
          sprite.callback = DeepVerticalSquishBounce;
      }


      private void Anim_HorizontalJumps(Sprite sprite)
      {
          int counter = sprite.data[2];
          TryFlipX(sprite);
          if (counter > 512)
          {
              sprite.callback = WaitAnimEnd;
              sprite.x2 = 0;
              sprite.y2 = 0;
          }
          else
          {
              switch (sprite.data[2] / 128)
              {
              case 0:
                  sprite.x2 = -(counter % 128 * 8) / 128;
                  break;
              case 1:
                  sprite.x2 = (counter % 128 / 16) - 8;
                  break;
              case 2:
                  sprite.x2 = (counter % 128 / 16);
                  break;
              case 3:
                  sprite.x2 = -(counter % 128 * 8) / 128 + 8;
                  break;
              }

              sprite.y2 = -(Sin(counter % 128, 8));
          }

          sprite.data[2] += 12;
          TryFlipX(sprite);
      }


      private void Anim_HorizontalJumpsVerticalStretch(Sprite sprite)
      {
          byte id = unchecked((byte)(sprite.data[0] = AddNewAnim()));
          sAnims[id].data = -1;
          HandleStartAffineAnim(sprite);
          sprite.data[3] = 0;
          HorizontalJumpsVerticalStretch_0(sprite);
          sprite.callback = HorizontalJumpsVerticalStretch_0;
      }


      private void HorizontalJumpsVerticalStretch_0(Sprite sprite)
      {
          if (sAnims[sprite.data[0]].delay != 0)
          {
              sAnims[sprite.data[0]].delay--;
          }
          else
          {
              int counter;

              TryFlipX(sprite);
              counter = sprite.data[2];
              if (sprite.data[2] > 128)
              {
                  sprite.data[2] = 0;
                  sprite.callback = HorizontalJumpsVerticalStretch_1;
              }
              else
              {
                  int var_ = 8 * sAnims[sprite.data[0]].data;
                  sprite.x2 = var_ * (counter % 128) / 128;
                  sprite.y2 = -(Sin(counter % 128, 8));
                  sprite.data[2] += 12;
              }

              TryFlipX(sprite);
          }
      }


      private void HorizontalJumpsVerticalStretch_1(Sprite sprite)
      {
          TryFlipX(sprite);
          if (sprite.data[2] > 48)
          {
              HandleSetAffineData(sprite, 256, 256, 0);
              sprite.y2 = 0;
              sprite.data[2] = 0;
              sprite.callback = HorizontalJumpsVerticalStretch_2;
          }
          else
          {
              short yDelta;
              short yScale = unchecked((short)(Sin(sprite.data[4], 64) + 256));
              if (sprite.data[2] >= 16 && sprite.data[2] <= 31)
              {
                  sprite.data[3] += 8;
                  sprite.x2 -= sAnims[sprite.data[0]].data;
              }

              yDelta = unchecked((short)(0));
              if (yScale > 256)
                  yDelta = unchecked((short)((256 - yScale) / 8));

              sprite.y2 = -(Sin(sprite.data[3], 20)) - yDelta;
              HandleSetAffineData(sprite, 256 - Sin(sprite.data[4], 32), yScale, 0);
              sprite.data[2]++;
              sprite.data[4] += 8;
              sprite.data[4] &= 0xFF;
          }

          TryFlipX(sprite);
      }


      private void HorizontalJumpsVerticalStretch_2(Sprite sprite)
      {
          int counter;

          TryFlipX(sprite);
          counter = sprite.data[2];
          if (counter > 128)
          {
              if (sAnims[sprite.data[0]].runs > 1)
              {
                  sAnims[sprite.data[0]].runs--;
                  sAnims[sprite.data[0]].delay = 10;
                  sprite.data[3] = 0;
                  sprite.data[2] = 0;
                  sprite.data[4] = 0;
                  sprite.callback = HorizontalJumpsVerticalStretch_0;
              }
              else
              {
                  ResetSpriteAfterAnim(sprite);
                  sprite.callback = WaitAnimEnd;
              }

              sprite.x2 = 0;
              sprite.y2 = 0;
          }
          else
          {
              int var_ = sAnims[sprite.data[0]].data;

              sprite.x2 = var_ * ((counter % 128) * 8) / 128 + 8 * -var_;
              sprite.y2 = -(Sin(counter % 128, 8));
          }

          sprite.data[2] += 12;
          TryFlipX(sprite);
      }


      private void RotateToSides(Sprite sprite)
      {
          if (sprite.data[2] == 0)
          {
              HandleStartAffineAnim(sprite);
              sprite.data[2]++;
          }

          TryFlipX(sprite);
          if (sprite.data[7] > 254)
          {
              sprite.x2 = 0;
              sprite.y2 = 0;
              HandleSetAffineData(sprite, 256, 256, 0);
              if (sAnims[sprite.data[0]].runs > 1)
              {
                  sAnims[sprite.data[0]].runs--;
                  sprite.data[2] = 0;
                  sprite.data[7] = 0;
              }
              else
              {
                  ResetSpriteAfterAnim(sprite);
                  sprite.callback = WaitAnimEnd;
              }

              TryFlipX(sprite);
          }
          else
          {
              ushort rotation;

              sprite.x2 = -(Sin(sprite.data[7], 16));
              rotation = unchecked((ushort)(Sin(sprite.data[7], 32)));
              HandleSetAffineData(sprite, 256, 256, rotation << 8);
              sprite.data[7] += sAnims[sprite.data[0]].rotation;
              TryFlipX(sprite);
          }
      }


