                  sign = unchecked((sbyte)(-1));

              if ((sprite.data[2] % 4) / 2 == 0)
              {
                  sprite.x2 = Sin((sprite.data[2] * 128 / 40) % 256, 16) * sign;
                  sprite.y2 = -(sprite.x2);
              }
              else
              {
                  sprite.x2 = -(Sin((sprite.data[2] * 128 / 40) % 256, 16)) * sign;
                  sprite.y2 = sprite.x2;
              }
          }

          sprite.data[2]++;
          TryFlipX(sprite);
      }


      private void Anim_GrowInStages(Sprite sprite)
      {
          TryFlipX(sprite);
          if (sprite.data[2] == 0)
          {
              HandleStartAffineAnim(sprite);
              sprite.data[5] = 0;
              sprite.data[6] = 0;
              sprite.data[7] = 0;
              sprite.data[2]++;
          }

          if (sprite.data[6] > 0)
          {
              sprite.data[6]--;
              if (sprite.data[5] != 3)
              {
                  short scale = unchecked((short)((8 * sprite.data[6]) / 20));
                  scale = unchecked((short)(Sin(sprite.data[7] - scale, 64)));
                  HandleSetAffineData(sprite, 256 - scale, 256 - scale, 0);
              }
          }
          else
          {
              short var_;

              if (sprite.data[5] == 3)
              {
                  if (sprite.data[7] > 63)
                  {
                      sprite.data[7] = 64;
                      HandleSetAffineData(sprite, 256, 256, 0);
                      ResetSpriteAfterAnim(sprite);
                      sprite.callback = WaitAnimEnd;
                  }
                  var_ = unchecked((short)(Cos(sprite.data[7], 64)));
              }
              else
              {
                  var_ = unchecked((short)(Sin(sprite.data[7], 64)));
                  if (sprite.data[7] > 63)
                  {
                      sprite.data[5] = 3;
                      sprite.data[6] = 10;
                      sprite.data[7] = 0;
                  }
                  else
                  {
                      if (var_ > 48 && sprite.data[5] == 1)
                      {
                          sprite.data[5] = 2;
                          sprite.data[6] = 20;
                      }
                      else if (var_ > 16 && sprite.data[5] == 0)
                      {
                          sprite.data[5] = 1;
                          sprite.data[6] = 20;
                      }
                  }
              }

              sprite.data[7] += 2;
              HandleSetAffineData(sprite, 256 - var_, 256 - var_, 0);
          }

          TryFlipX(sprite);
      }


