      private void SetHorizontalDip(Sprite sprite)
      {
          ushort index = unchecked((ushort)(Sin((sprite.data[2] * 128) / sprite.data[7], sprite.data[5])));
          sprite.data[6] = -(index << 8);
          SetPosForRotation(sprite, index, sprite.data[4], 0);
          HandleSetAffineData(sprite, 256, 256, sprite.data[6]);
      }


      private void Anim_HorizontalDip(Sprite sprite)
      {
          if (sprite.data[2] == 0)
          {
              HandleStartAffineAnim(sprite);
              sprite.data[7] = 60;
              sprite.data[5] = 8;
              sprite.data[4] = -32;
              sprite.data[3] = 1;
              sprite.data[0] = 0;
          }

          if (sprite.data[2] > sprite.data[7])
          {
              HandleSetAffineData(sprite, 256, 256, 0);
              sprite.x2 = 0;
              sprite.y2 = 0;
              sprite.data[0]++;
              if (sprite.data[3] <= sprite.data[0])
              {
                  ResetSpriteAfterAnim(sprite);
                  sprite.callback = WaitAnimEnd;
                  return;
              }
              else
              {
                  sprite.data[2] = 0;
              }
          }
          else
          {
              SetHorizontalDip(sprite);
          }

          sprite.data[2]++;
      }


