      private void ShrinkGrowVibrate(Sprite sprite)
      {
          if (sprite.data[2] > sprite.data[7])
          {
              sprite.y2 = 0;
              HandleSetAffineData(sprite, 256, 256, 0);
              ResetSpriteAfterAnim(sprite);
              sprite.callback = WaitAnimEnd;
          }
          else
          {
              sbyte sinY;
              ushort y;
              short index = unchecked((short)((ToU16(sprite.data[2] % sprite.data[6] * 256) / sprite.data[6]) % 256));
              if (sprite.data[2] % 2 == 0)
              {
                  sprite.data[4] = Sin(index, 32) + 256;
                  sprite.data[5] = Sin(index, 32) + 256;
                  sinY = unchecked((sbyte)(Sin(index, 32)));
              }
              else
              {
                  sprite.data[4] = Sin(index, 8) + 256;
                  sprite.data[5] = Sin(index, 8) + 256;
                  sinY = unchecked((sbyte)(Sin(index, 8)));
              }

              y = unchecked((ushort)(sinY / 8));
              sprite.y2 = y;
              HandleSetAffineData(sprite, sprite.data[4], sprite.data[5], 0);
          }

          sprite.data[2]++;
      }


