      private void JoltRight(Sprite sprite)
      {
          TryFlipX(sprite);
          sprite.x2 -= sprite.data[2];
          if (sprite.x2 <= -sprite.data[6])
          {
              sprite.x2 = -sprite.data[6];
              sprite.data[7] = 2;
              sprite.callback = JoltRight_0;
          }

          TryFlipX(sprite);
      }


      private void JoltRight_0(Sprite sprite)
      {
          TryFlipX(sprite);
          sprite.x2 += sprite.data[7];
          sprite.data[7]++;
          if (sprite.x2 >= 0)
              sprite.callback = JoltRight_1;

          TryFlipX(sprite);
      }


      private void JoltRight_1(Sprite sprite)
      {
          TryFlipX(sprite);
          sprite.x2 += sprite.data[7];
          sprite.data[7]++;
          if (sprite.x2 > sprite.data[6])
          {
              sprite.x2 = sprite.data[6];
              sprite.callback = JoltRight_2;
          }

          TryFlipX(sprite);
      }


      private void JoltRight_2(Sprite sprite)
      {
          TryFlipX(sprite);
          if (sprite.data[3] >= sprite.data[5])
          {
              sprite.callback = JoltRight_3;
          }
          else
          {
              sprite.x2 += sprite.data[4];
              sprite.data[4] *= -1;
              sprite.data[3]++;
          }

          TryFlipX(sprite);
      }


      private void JoltRight_3(Sprite sprite)
      {
          TryFlipX(sprite);
          sprite.x2 -= 2;
          if (sprite.x2 <= 0)
          {
              sprite.x2 = 0;
              ResetSpriteAfterAnim(sprite);
              sprite.callback = WaitAnimEnd;
          }

          TryFlipX(sprite);
      }


