      private void SetShakeFlashYellowPos(Sprite sprite)
      {
          sprite.x2 = sprite.data[1];
          if (sprite.data[0] > 1)
          {
              sprite.data[1] *= -1;
              sprite.data[0] = 0;
          }
          else
          {
              sprite.data[0]++;
          }
      }


      private void ShakeFlashYellow(Sprite sprite)
      {
          YellowFlashData[] array = sShakeYellowFlashData[sprite.data[3]];
          SetShakeFlashYellowPos(sprite);
          if (array[sprite.data[6]].time == 255)
          {
              sprite.x2 = 0;
              sprite.callback = WaitAnimEnd;
          }
          else
          {
              if (sprite.data[4] == 1)
              {
                  if (array[sprite.data[6]].isYellow)
                      BlendPalette(sprite.data[7], 16, 16, RGB_YELLOW);
                  else
                      BlendPalette(sprite.data[7], 16, 0, RGB_YELLOW);

                  sprite.data[4] = 0;
              }

              if (array[sprite.data[6]].time == sprite.data[5])
              {
                  sprite.data[4] = 1;
                  sprite.data[5] = 0;
                  sprite.data[6]++;
              }
              else
              {
                  sprite.data[5]++;
              }
          }
      }


